  2540  static SOPC_ReturnStatus ReadVariantArrayBuiltInType(SOPC_Buffer* buf,
  2541                                                       SOPC_BuiltinId builtInTypeId,
  2542                                                       SOPC_VariantArrayValue* array,
  2543                                                       int32_t* length,
  2544                                                       uint32_t nestedStructLevel)
  2545  {
  2546      if (nestedStructLevel >= SOPC_Internal_Common_GetEncodingConstants()->max_nested_struct)
  2547      {
  2548          return SOPC_STATUS_INVALID_STATE;
  2549      }
  2550      else if (builtInTypeId <= 0 || builtInTypeId > SOPC_BUILTINID_MAX + 1)
  2551      {
  2552          return SOPC_STATUS_INVALID_PARAMETERS;
  2553      }
  2554      SOPC_ReturnStatus status = SOPC_STATUS_OK;
  2555      const size_t eltOptimSize = getBuiltinOptimizableSize(builtInTypeId);
  2556      if (eltOptimSize > 0)
  2557      {
  2558          if (NULL == buf || NULL == length || NULL == array || NULL != array->BooleanArr)
  2559          {
  2560              return SOPC_STATUS_INVALID_PARAMETERS;
  2561          }
  2562          else if (nestedStructLevel >= SOPC_Internal_Common_GetEncodingConstants()->max_nested_struct)
  2563          {
  2564              return SOPC_STATUS_INVALID_STATE;
  2565          }
  2566
  2567          nestedStructLevel++;
  2568          status = SOPC_Int32_Read(length, buf, nestedStructLevel);
  2569
  2570          if (SOPC_STATUS_OK == status && *length < 0)
  2571          {
  2572              *length = 0;
  2573          }
  2574
  2575          if (SOPC_STATUS_OK == status && *length > SOPC_Internal_Common_GetEncodingConstants()->max_array_length)
  2576          {
  2577              status = SOPC_STATUS_OUT_OF_MEMORY;
  2578          }
  2579
  2580          if (SOPC_STATUS_OK == status && *length > 0 && (uint64_t) *length <= SIZE_MAX / eltOptimSize)
  2581          {
  2582              array->BooleanArr = SOPC_Calloc((size_t) *length, eltOptimSize);
  2583
  2584              if (NULL == array->BooleanArr)
  2585              {
  2586                  status = SOPC_STATUS_OUT_OF_MEMORY;
  2587              }
  2588              else
  2589              {
  2590                  status = SOPC_Buffer_Read(array->BooleanArr, buf, (uint32_t)((uint32_t)(*length) * eltOptimSize));
  2591                  if (SOPC_STATUS_OK != status)
  2592                  {
  2593                      status = SOPC_STATUS_ENCODING_ERROR;
  2594                  }
  2595              }
  2596
  2597              if (SOPC_STATUS_OK != status)
  2598              {
  2599                  SOPC_Free(array->BooleanArr);
  2600                  array->BooleanArr = NULL;
  2601                  *length = 0;
  2602              }
  2603          }
  2604      }
  2605      else
  2606      {
  2607          // Note : union fields content are all pointing to the same address.
  2608          // using array->BooleanArr to point array, but any other field would be possible
  2609          status = SOPC_Read_Array(buf, length, (void**) &array->BooleanArr,
  2610                                   SOPC_BuiltInType_HandlingTable[builtInTypeId].size,
  2611                                   SOPC_BuiltInType_EncodingTable[builtInTypeId].decode,
  2612                                   SOPC_BuiltInType_HandlingTable[builtInTypeId].initialize,
  2613                                   SOPC_BuiltInType_HandlingTable[builtInTypeId].clear, nestedStructLevel);
  2614      }
  2615      return status;
  2616  }
